member.summary:
The expiration of a cached object can be extended by a specified time if the object is retrieved
from the cache before the object expires.  If the object is not retrieved during the specified time, 
the object expires and is removed from the cache.

example.code:
public class RandomColorGenerator : ColorGenerator
{
	private Color[] _colors;

	public RandomColorGenerator()
	    :this(8)
	{
	}
  	public RandomColorGenerator(int numberOfColors)
	{
		if(numberOfColors <= 0)
			throw new Exception("Invalid parameter.");
		Random rand = new Random();
		_colors = new Color[numberOfColors];
		for(int i=0; i<numberOfColors; i++)
		{
			_colors[i] = Color.FromArgb(rand.Next()%255, rand.Next()%255, rand.Next()%255);

		}
	}

	public override Color GetColor(int index)
	{
		return _colors[Math.Abs(index % _colors.Length)];
	}
}

