example.code:
private void SetupAxis(Axis targetAxis)
{
    targetAxis.MajorDivisions.LabelFormat = new FormatString(FormatStringMode.Numeric, "F3");
}

private class CustomFormatString : FormatString
{
    private int scalingFactor;
    public CustomFormatString(int scaling) : base(FormatStringMode.Numeric, "G5")
    {
        scalingFactor = scaling;
    }
    public override string FormatDouble(double value)
    {
        return base.FormatDouble(value * scalingFactor);
    }
}

private class CustomFormatString : FormatString
{
    public CustomFormatString() : base(FormatStringMode.Numeric, "G5")
    {
    }
    public override string FormatDouble(double value)
    {
        return base.FormatDouble(value * 1000);
    }
}

